{
  "name": "opencode-bmad-workflow",
  "version": "0.4.1",
  "description": "BMAD workflow plugin for opencode — automates epic, feature, sprint and code review workflows using specialized AI agents",
  "type": "module",
  "main": "dist/index.js",
  "exports": {
    ".": "./dist/index.js"
  },
  "bin": {
    "opencode-bmad-workflow": "install.js"
  },
  "scripts": {
    "build": "bun build plugins/index.ts --outdir dist --target bun --format esm",
    "test": "bun test plugins/parsers",
    "prepublishOnly": "bun run test && bun run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "bmad",
    "workflow",
    "ai",
    "agents"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Alex-stack-cell/opencode-bmad-workflow.git"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.4.7",
    "@opencode-ai/sdk": "1.4.1",
    "chalk": "^5.6.2"
  },
  "devDependencies": {
    "bun-types": "^1.3.11"
  }
}
